const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wolfVolcano = ee.Geometry.Point(-91.3500, 0.0270);
  const buffer = wolfVolcano.buffer(5000); // 5 km radius around the volcano

  const date6 = '2022-01-06';
  const date7 = '2022-01-07';
  const nextDay6 = '2022-01-07'; // End date is exclusive
  const nextDay7 = '2022-01-08';

  // VIIRS DNB cloud mask function
  // Cloud mask: 0 (clear), 1 (cloud), 2 (probably cloud), 3 (shadow).
  // We want to keep only clear pixels.
  const applyCloudMask = function(image) {
    const cloudMask = image.select('cloud_mask').eq(0);
    return image.updateMask(cloudMask).select('avg_rad');
  };

  // Function to process data for a single day
  const processDay = async (date, endDate, dayLabel) => {
    let collection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_VCMCFG')
      .filterBounds(buffer)
      .filterDate(date, endDate);

    const collectionSize = await collection.size().getInfo();
    console.log(`${dayLabel} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { value: null, pixels: 0, status: 'C1' };
    }

    // Get the first image (should be one per day if available)
    let image = ee.Image(collection.first());

    // Apply cloud mask and select the avg_rad band
    let maskedImage = applyCloudMask(image);

    // Calculate valid pixel count
    const pixelCount = await maskedImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: buffer,
      scale: 1000, // Use a sufficiently large scale
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    console.log(`${dayLabel} Valid Pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      return { value: null, pixels: 0, status: 'C2' };
    }

    // Calculate mean brightness
    const meanBrightness = await maskedImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 1000,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    if (meanBrightness === null || isNaN(meanBrightness)) {
      return { value: null, pixels: pixelCount, status: 'C3' };
    }

    return { value: meanBrightness, pixels: pixelCount, status: 'OK' };
  };

  // Process data for Jan 6, 2022
  const result6 = await processDay(date6, nextDay6, 'Jan 6, 2022');
  if (result6.status !== 'OK') {
    console.log(`Failed for Jan 6: ${result6.status}`);
    console.log(result6.status);
    return;
  }

  // Process data for Jan 7, 2022
  const result7 = await processDay(date7, nextDay7, 'Jan 7, 2022');
  if (result7.status !== 'OK') {
    console.log(`Failed for Jan 7: ${result7.status}`);
    console.log(result7.status);
    return;
  }

  console.log(`Jan 6, 2022 Brightness: ${result6.value.toFixed(2)} nW/cm²/sr`);
  console.log(`Jan 7, 2022 Brightness: ${result7.value.toFixed(2)} nW/cm²/sr`);

  // 5. Validation & Final Answer
  if (result7.value > result6.value) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
